  def icon(nombre, clase: "icon")
    tag.svg(ICONOS.fetch(nombre).html_safe, class: clase, viewBox: "0 0 24 24", "aria-hidden": true)
  end

  # Separa un texto en palabras envueltas en spans para animarlas.
  # Lo que va entre *asteriscos* se marca como énfasis.
  def split_words(texto)
    safe_join(
      texto.split(/(\*[^*]+\*|\s+)/).reject(&:empty?).map do |trozo|
        if trozo.match?(/\A\s+\z/)
          " "
        elsif trozo.start_with?("*")
          trozo[1..-2].split(" ").map { |p| tag.span(tag.span(p, class: "w"), class: "wm em") }.then { |s| safe_join(s, " ") }
        else
          tag.span(tag.span(trozo, class: "w"), class: "wm")
        end
      end
    )
  end
end
